-- Add Gomoa Wonderland to the attractions dataset
insert into public.destinations ("id", "name", "category", "categoryName", "region", "location", "image", "rating", "reviews", "fee", "hours", "bestTime", "accessibility", "lat", "lng", "shortDesc", "fullDesc", "highlights", "nearbyHotels", "guideContact") values
('gomoa-wonderland', 'Gomoa Wonderland', 'cultural', 'Amusement Park', 'Central Region', 'Gomoa Fetteh, near Winneba', 'assets/images/attractions/gomoa-wonderland.jpg', 4.4, 0, 'Entry Fee Applies', 'Open Daily', 'Weekdays (quieter)', 'Wheelchair accessible walkways', 5.34, -0.62, 'A family amusement park near Winneba with rides, swimming pools, and leisure facilities on the central coast.', 'Gomoa Wonderland is one of Ghana''s best-known leisure and amusement parks, located at Gomoa Fetteh along the Accra–Cape Coast highway. It offers carnival rides, splash pools, picnic lawns, and kid-friendly attractions, making it a popular day-trip and weekend outing on the central coast.', '["Rides & Games", "Splash Pools", "Family Picnic Lawns", "Coastal Highway Stop"]', '[]', '')
on conflict (id) do update set "id"=excluded."id", "name"=excluded."name", "category"=excluded."category", "categoryName"=excluded."categoryName", "region"=excluded."region", "location"=excluded."location", "image"=excluded."image", "rating"=excluded."rating", "reviews"=excluded."reviews", "fee"=excluded."fee", "hours"=excluded."hours", "bestTime"=excluded."bestTime", "accessibility"=excluded."accessibility", "lat"=excluded."lat", "lng"=excluded."lng", "shortDesc"=excluded."shortDesc", "fullDesc"=excluded."fullDesc", "highlights"=excluded."highlights", "nearbyHotels"=excluded."nearbyHotels", "guideContact"=excluded."guideContact";

update public.regions set destinations = '["cape-coast-castle", "kakum-national-park", "elmina-castle", "fort-st-jago", "fort-victoria", "fort-william-cape-coast", "fort-royal", "fort-mccarthy", "fort-amsterdam-abandzi", "fort-good-hope", "fort-patience", "fort-nassau-mouri", "fort-william-anomabu", "assin-manso-slave-river", "posuban-shrines", "gomoa-wonderland"]' where id = 'central';
